CREATE TABLE mv_pk (id INTEGER PRIMARY KEY, label TEXT);
 CREATE TABLE mv_heap (id INTEGER, label TEXT);
 CREATE INDEX mv_label ON mv_pk(label);
 INSERT INTO mv_pk VALUES (1,'value-001'),(2,'value-002'),(3,'value-003'),(4,'value-004');
 INSERT INTO mv_heap SELECT * FROM mv_pk;
 UPDATE mv_pk SET label='updated' WHERE id=3;
 UPDATE mv_heap SET label='updated' WHERE id=3;
 DELETE FROM mv_pk WHERE id=4;
 DELETE FROM mv_heap WHERE id=4;
CREATE SCHEMA mv_schema;
 CREATE TABLE mv_schema.items (id INTEGER PRIMARY KEY);
 INSERT INTO mv_schema.items VALUES (7);
CREATE TYPE mv_mood AS ENUM ('quiet','happy');
 CREATE TABLE mv_enum(id INTEGER PRIMARY KEY,mood mv_mood);
 INSERT INTO mv_enum VALUES(1,'happy');
CREATE SEQUENCE mv_seq START WITH 17;
 SELECT nextval('mv_seq');
CREATE TABLE mv_schema.serials(id SERIAL PRIMARY KEY);
 INSERT INTO mv_schema.serials DEFAULT VALUES;
 CREATE INDEX items_idx ON mv_schema.items(id);
